12	
13	#ifndef ORC_RT_WRAPPERFUNCTION_H
14	#define ORC_RT_WRAPPERFUNCTION_H
15	
16	#include "orc-rt-c/WrapperFunction.h"
17	#include "orc-rt/CallableTraitsHelper.h"
18	#include "orc-rt/Error.h"
19	#include "orc-rt/ExecutorAddress.h"
20	#include "orc-rt/bind.h"
21	#include "orc-rt/move_only_function.h"
22	
23	#include <utility>
24	
25	namespace orc_rt {
26	
27	/// A C++ convenience wrapper for orc_rt_WrapperFunctionBuffer. Auto-disposes
28	/// the contained result on destruction.
29	class WrapperFunctionBuffer {
30	public:
31	  /// Create a default WrapperFunctionBuffer.
32	  WrapperFunctionBuffer() { orc_rt_WrapperFunctionBufferInit(&B); }
33	
34	  /// Create a WrapperFunctionBuffer from a WrapperFunctionBuffer. This
35	  /// instance takes ownership of the result object and will automatically
36	  /// call dispose on the result upon destruction.
37	  explicit WrapperFunctionBuffer(orc_rt_WrapperFunctionBuffer B) : B(B) {}
38	
39	  WrapperFunctionBuffer(const WrapperFunctionBuffer &) = delete;
40	  WrapperFunctionBuffer &operator=(const WrapperFunctionBuffer &) = delete;
41	
42	  WrapperFunctionBuffer(WrapperFunctionBuffer &&Other) {
43	    orc_rt_WrapperFunctionBufferInit(&B);
44	    std::swap(B, Other.B);
45	  }
46	
47	  WrapperFunctionBuffer &operator=(WrapperFunctionBuffer &&Other) {
48	    orc_rt_WrapperFunctionBufferDispose(&B);
49	    orc_rt_WrapperFunctionBufferInit(&B);
50	    std::swap(B, Other.B);
51	    return *this;
52	  }
53	
54	  ~WrapperFunctionBuffer() { orc_rt_WrapperFunctionBufferDispose(&B); }
55	
56	  /// Relinquish ownership of and return the
57	  /// orc_rt_WrapperFunctionBuffer.
58	  orc_rt_WrapperFunctionBuffer release() {
59	    orc_rt_WrapperFunctionBuffer Tmp;
60	    orc_rt_WrapperFunctionBufferInit(&Tmp);
61	    std::swap(B, Tmp);
62	    return Tmp;
63	  }
64	
65	  /// Get a pointer to the data contained in this instance.
66	  char *data() { return orc_rt_WrapperFunctionBufferData(&B); }
67	
68	  /// Get a pointer to the data contained is this instance.
69	  const char *data() const { return orc_rt_WrapperFunctionBufferConstData(&B); }
70	
71	  /// Returns the size of the data contained in this instance.
72	  size_t size() const { return orc_rt_WrapperFunctionBufferSize(&B); }
73	
74	  /// Returns true if this value is equivalent to a default-constructed
75	  /// WrapperFunctionBuffer.
76	  bool empty() const { return orc_rt_WrapperFunctionBufferEmpty(&B); }
77	
78	  /// Create a WrapperFunctionBuffer with the given size and return a pointer
79	  /// to the underlying memory.
80	  static WrapperFunctionBuffer allocate(size_t Size) {
81	    return WrapperFunctionBuffer(orc_rt_WrapperFunctionBufferAllocate(Size));
82	  }
83	
84	  /// Copy from the given char range.
85	  static WrapperFunctionBuffer copyFrom(const char *Source, size_t Size) {
86	    return WrapperFunctionBuffer(
87	        orc_rt_CreateWrapperFunctionBufferFromRange(Source, Size));
88	  }
89	
90	  /// Copy from the given null-terminated string (includes the null-terminator).
91	  static WrapperFunctionBuffer copyFrom(const char *Source) {
92	    return WrapperFunctionBuffer(
93	        orc_rt_CreateWrapperFunctionBufferFromString(Source));
94	  }
95	
96	  /// Create an out-of-band error by copying the given string.
97	  static WrapperFunctionBuffer createOutOfBandError(const char *Msg) {
98	    return WrapperFunctionBuffer(
99	        orc_rt_CreateWrapperFunctionBufferFromOutOfBandError(Msg));
100	  }
101	
102	  /// If this value is an out-of-band error then this returns the error message,
103	  /// otherwise returns nullptr.
104	  const char *getOutOfBandError() const {
105	    return orc_rt_WrapperFunctionBufferGetOutOfBandError(&B);
106	  }
107	
108	private:
109	  orc_rt_WrapperFunctionBuffer B;
110	};
111	
112	namespace detail {
113	
114	template <typename RetT, typename ReturnT, typename... ArgTs>
115	struct WFHandlerTraitsImpl {
116	  static_assert(std::is_void_v<RetT>,
117	                "Async wrapper function handler must return void");
118	  typedef ReturnT YieldType;
119	  typedef std::tuple<std::decay_t<ArgTs>...> ArgTupleType;
120	
121	  // Forwards arguments based on the parameter types of the handler.
122	  template <typename FnT> class ForwardArgsAsRequested {
123	  public:
124	    ForwardArgsAsRequested(FnT &&Fn) : Fn(std::move(Fn)) {}
125	    void operator()(ArgTs &...Args) { Fn(std::forward<ArgTs>(Args)...); }
126	
127	  private:
128	    FnT Fn;
129	  };
130	
131	  template <typename FnT>
132	  static ForwardArgsAsRequested<std::decay_t<FnT>>
133	  forwardArgsAsRequested(FnT &&Fn) {
134	    return ForwardArgsAsRequested<std::decay_t<FnT>>(std::forward<FnT>(Fn));
135	  }
136	};
137	
138	template <bool /* is_const */, bool /* is_noexcept */, typename... Ts>
139	struct WFHandlerTraitsImplAdapter : WFHandlerTraitsImpl<Ts...> {};
140	
141	template <typename C>
142	using WFHandlerTraits = CallableTraitsHelper<WFHandlerTraitsImplAdapter, C>;
143	
144	template <typename Serializer> class StructuredYieldBase {
145	public:
146	  StructuredYieldBase(orc_rt_SessionRef S, orc_rt_WrapperFunctionReturn Return,
147	                      uint64_t CallId, Serializer &&Z)
148	      : S(S), Return(Return), CallId(CallId), Z(std::forward<Serializer>(Z)) {}
149	
150	protected:
151	  orc_rt_SessionRef S;
152	  orc_rt_WrapperFunctionReturn Return;
153	  uint64_t CallId;
154	  std::decay_t<Serializer> Z;
155	};
156	
157	template <typename RetT, typename Serializer> class StructuredYield;
158	
159	template <typename RetT, typename Serializer>
160	class StructuredYield<std::tuple<RetT>, Serializer>
161	    : public StructuredYieldBase<Serializer> {
162	public:
163	  using StructuredYieldBase<Serializer>::StructuredYieldBase;
164	  void operator()(RetT &&R) {
165	    if (auto ResultBytes = this->Z.result().serialize(std::forward<RetT>(R)))
166	      this->Return(this->S, ResultBytes->release(), this->CallId);
167	    else
168	      this->Return(this->S,
169	                   WrapperFunctionBuffer::createOutOfBandError(
170	                       "Could not serialize wrapper function result data")
171	                       .release(),
172	                   this->CallId);
173	  }
174	};
175	
176	template <typename Serializer>
177	class StructuredYield<std::tuple<>, Serializer>
178	    : public StructuredYieldBase<Serializer> {
179	public:
180	  using StructuredYieldBase<Serializer>::StructuredYieldBase;
181	  void operator()() {
182	    this->Return(this->S, WrapperFunctionBuffer().release(), this->CallId);
183	  }
184	};
185	
186	template <typename T, typename Serializer> struct ResultDeserializer;
187	
188	template <typename T, typename Serializer>
189	struct ResultDeserializer<std::tuple<Expected<T>>, Serializer> {
190	  static Expected<T> deserialize(WrapperFunctionBuffer ResultBytes,
191	                                 Serializer &S) {
192	    if (auto Val = S.result().template deserialize<std::tuple<T>>(
193	            std::move(ResultBytes)))
194	      return Expected<T>(std::move(std::get<0>(*Val)),
195	                         ForceExpectedSuccessValue());
196	    else
197	      return make_error<StringError>("Could not deserialize result");
198	  }
199	};
200	
201	template <typename Serializer>
202	struct ResultDeserializer<std::tuple<Error>, Serializer> {
203	  static Error deserialize(WrapperFunctionBuffer ResultBytes, Serializer &S) {
204	    assert(ResultBytes.empty());
205	    return Error::success();
206	  }
207	};
208	
209	} // namespace detail
210	
211	/// Provides call and handle utilities to simplify writing and invocation of
212	/// wrapper functions in C++.
213	struct WrapperFunction {
214	
215	  /// Wraps an asynchronous method (a method returning void, and taking a
216	  /// return callback as its first argument) for use with
217	  /// WrapperFunction::handle.
218	  ///
219	  /// AsyncMethod's call operator takes an ExecutorAddr as its second argument,
220	  /// casts it to a ClassT*, and then calls the wrapped method on that pointer,
221	  /// forwarding the return callback and any subsequent arguments (after the
222	  /// second argument representing the object address).
223	  ///
224	  /// This utility removes some of the boilerplate from writing wrappers for
225	  /// method calls.
226	  template <typename ClassT, typename ReturnT, typename... ArgTs>
227	  struct AsyncMethod {
228	    AsyncMethod(void (ClassT::*M)(ReturnT, ArgTs...)) : M(M) {}
229	    void operator()(ReturnT &&Return, ExecutorAddr Obj, ArgTs &&...Args) {
230	      (Obj.toPtr<ClassT *>()->*M)(std::forward<ReturnT>(Return),
231	                                  std::forward<ArgTs>(Args)...);
232	    }
233	
234	  private:
235	    void (ClassT::*M)(ReturnT, ArgTs...);
236	  };
237	
238	  /// Create an AsyncMethod wrapper for the given method pointer. The given
239	  /// method should be asynchronous: returning void, and taking a return
240	  /// callback as its first argument.
241	  ///
242	  /// The handWithAsyncMethod function can be used to remove some of the
243	  /// boilerplate from writing wrappers for method calls:
244	  ///
245	  ///   @code{.cpp}
246	  ///   class MyClass {
247	  ///   public:
248	  ///     void myMethod(move_only_function<void(std::string)> Return,
249	  //                    uint32_t X, bool Y) { ... }
250	  ///   };
251	  ///
252	  ///   // SPS Method signature -- note MyClass object address as first
253	  ///   // argument.
254	  ///   using SPSMyMethodWrapperSignature =
255	  ///     SPSString(SPSExecutorAddr, uint32_t, bool);
256	  ///
257	  ///
258	  ///   static void adder_add_async_sps_wrapper(
259	  ///       orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
260	  ///       orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {
261	  ///     using SPSSig = SPSString(SPSExecutorAddr, int32_t, bool);
262	  ///     SPSWrapperFunction<SPSSig>::handle(
263	  ///         S, ArgBytes, Return, CallId,
264	  ///         WrapperFunction::handleWithAsyncMethod(&MyClass::myMethod));
265	  ///   }
266	  ///   @endcode
267	  ///
268	  template <typename ClassT, typename ReturnT, typename... ArgTs>
269	  static AsyncMethod<ClassT, ReturnT, ArgTs...>
270	  handleWithAsyncMethod(void (ClassT::*M)(ReturnT, ArgTs...)) {
271	    return AsyncMethod<ClassT, ReturnT, ArgTs...>(M);
272	  }
273	
274	  /// Wraps a synchronous method (an ordinary method that returns its result,
275	  /// as opposed to an asynchronous method, see AsyncMethod) for use with
276	  /// WrapperFunction::handle.
277	  ///
278	  /// SyncMethod's call operator takes a return callback as its first argument
279	  /// and an ExecutorAddr as its second argument. The ExecutorAddr argument is
280	  /// cast to a ClassT*, and then called passing the subsequent arguments
281	  /// (after the second argument representing the object address). The Return
282	  /// callback is then called on the value returned from the method.
283	  ///
284	  /// This utility removes some of the boilerplate from writing wrappers for
285	  /// method calls.
286	  template <typename ClassT, typename RetT, typename... ArgTs>
287	  class SyncMethod {
288	  public:
289	    SyncMethod(RetT (ClassT::*M)(ArgTs...)) : M(M) {}
290	
291	    void operator()(move_only_function<void(RetT)> Return, ExecutorAddr Obj,
292	                    ArgTs &&...Args) {
293	      Return((Obj.toPtr<ClassT *>()->*M)(std::forward<ArgTs>(Args)...));
294	    }
295	
296	  private:
297	    RetT (ClassT::*M)(ArgTs...);
298	  };
299	
300	  /// Create an SyncMethod wrapper for the given method pointer. The given
301	  /// method should be synchronous, i.e. returning its result (as opposed to
302	  /// asynchronous, see AsyncMethod).
303	  ///
304	  /// The handWithAsyncMethod function can be used to remove some of the
305	  /// boilerplate from writing wrappers for method calls:
306	  ///
307	  ///   @code{.cpp}
308	  ///   class MyClass {
309	  ///   public:
310	  ///     std::string myMethod(uint32_t X, bool Y) { ... }
311	  ///   };
312	  ///
313	  ///   // SPS Method signature -- note MyClass object address as first
314	  ///   // argument.
315	  ///   using SPSMyMethodWrapperSignature =
316	  ///     SPSString(SPSExecutorAddr, uint32_t, bool);
317	  ///
318	  ///
319	  ///   static void adder_add_sync_sps_wrapper(
320	  ///       orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
321	  ///       orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {
322	  ///     using SPSSig = SPSString(SPSExecutorAddr, int32_t, bool);
323	  ///     SPSWrapperFunction<SPSSig>::handle(
324	  ///         S, ArgBytes, Return, CallId,
325	  ///         WrapperFunction::handleWithSyncMethod(&Adder::addSync));
326	  ///   }
327	  ///   @endcode
328	  ///
329	  template <typename ClassT, typename RetT, typename... ArgTs>
330	  static SyncMethod<ClassT, RetT, ArgTs...>
331	  handleWithSyncMethod(RetT (ClassT::*M)(ArgTs...)) {
332	    return SyncMethod<ClassT, RetT, ArgTs...>(M);
333	  }
334	
335	  /// Make a call to a wrapper function.
336	  ///
337	  /// This utility serializes and deserializes arguments and return values
338	  /// (using the given Serializer), and calls the wrapper function via the
339	  /// given Caller object.
340	  template <typename Caller, typename Serializer, typename ResultHandler,
341	            typename... ArgTs>
342	  static void call(Caller &&C, Serializer &&Z, ResultHandler &&RH,
343	                   ArgTs &&...Args) {
344	    typedef CallableArgInfo<ResultHandler> ResultHandlerTraits;
345	    static_assert(std::is_void_v<typename ResultHandlerTraits::return_type>,
346	                  "Result handler should return void");
347	    static_assert(
348	        std::tuple_size_v<typename ResultHandlerTraits::args_tuple_type> == 1,
349	        "Result-handler should have exactly one argument");
350	    typedef typename ResultHandlerTraits::args_tuple_type ResultTupleType;
351	
352	    if (auto ArgBytes = Z.arguments().serialize(std::forward<ArgTs>(Args)...)) {
353	      C(
354	          [RH = std::move(RH),
355	           Z = std::move(Z)](WrapperFunctionBuffer ResultBytes) mutable {
356	            if (const char *ErrMsg = ResultBytes.getOutOfBandError())
357	              RH(make_error<StringError>(ErrMsg));
358	            else
359	              RH(detail::ResultDeserializer<ResultTupleType, Serializer>::
360	                     deserialize(std::move(ResultBytes), Z));
361	          },
362	          std::move(*ArgBytes));
363	    } else
364	      RH(make_error<StringError>(
365	          "Could not serialize wrapper function call arguments"));
366	  }
367	
368	  /// Simplifies implementation of wrapper functions in C++.
369	  ///
370	  /// This utility deserializes and serializes arguments and return values
371	  /// (using the given Serializer), and calls the given handler.
372	  template <typename Serializer, typename Handler>
373	  static void handle(orc_rt_SessionRef S, WrapperFunctionBuffer ArgBytes,
374	                     orc_rt_WrapperFunctionReturn Return, uint64_t CallId,
375	                     Serializer &&Z, Handler &&H) {
376	    typedef detail::WFHandlerTraits<Handler> HandlerTraits;
377	    typedef typename HandlerTraits::ArgTupleType ArgTuple;
378	    typedef typename HandlerTraits::YieldType Yield;
379	    static_assert(std::is_void_v<typename CallableArgInfo<Yield>::return_type>,
380	                  "Return callback must return void");
381	    typedef typename CallableArgInfo<Yield>::args_tuple_type RetTupleType;
382	
383	    if (ArgBytes.getOutOfBandError())
384	      return Return(S, ArgBytes.release(), CallId);
385	
386	    if (auto Args = Z.arguments().template deserialize<ArgTuple>(ArgBytes))
387	      std::apply(HandlerTraits::forwardArgsAsRequested(bind_front(
388	                     std::forward<Handler>(H),
389	                     detail::StructuredYield<RetTupleType, Serializer>(
390	                         S, Return, CallId, std::move(Z)))),
391	                 *Args);
392	    else
393	      Return(S,
394	             WrapperFunctionBuffer::createOutOfBandError(
395	                 "Could not deserialize wrapper function arg data")
396	                 .release(),
397	             CallId);
398	  }
399	};
400	
401	} // namespace orc_rt
402	
403	#endif // ORC_RT_WRAPPERFUNCTION_H
