220	TEST(SPSWrapperFunctionUtilsTest, HandlerWithReferences) {
221	  // Test that we can handle by-value, by-ref, by-const-ref, and by-rvalue-ref
222	  // arguments, and that we generate the expected number of moves.
223	  OpCounter<0>::reset();
224	  OpCounter<1>::reset();
225	  OpCounter<2>::reset();
226	  OpCounter<3>::reset();
227	
228	  bool DidRun = false;
229	  SPSWrapperFunction<void(SPSOpCounter<0>, SPSOpCounter<1>, SPSOpCounter<2>,
230	                          SPSOpCounter<3>)>::
231	      call(
232	          DirectCaller(nullptr, handle_with_reference_types_sps_wrapper),
233	          [&](Error R) {
234	            cantFail(std::move(R));
235	            DidRun = true;
236	          },
237	          OpCounter<0>(), OpCounter<1>(), OpCounter<2>(), OpCounter<3>());
238	
239	  EXPECT_TRUE(DidRun);
240	
241	  // We expect two default constructions for each parameter: one for the
242	  // argument to call, and one for the object to deserialize into.
243	  EXPECT_EQ(OpCounter<0>::defaultConstructions(), 2U);
244	  EXPECT_EQ(OpCounter<1>::defaultConstructions(), 2U);
245	  EXPECT_EQ(OpCounter<2>::defaultConstructions(), 2U);
246	  EXPECT_EQ(OpCounter<3>::defaultConstructions(), 2U);
247	
248	  // Pass-by-value: we expect two moves (one for SPS transparent conversion,
249	  // one to copy the value to the parameter), and no copies.
250	  EXPECT_EQ(OpCounter<0>::moves(), 2U);
251	  EXPECT_EQ(OpCounter<0>::copies(), 0U);
252	
253	  // Pass-by-lvalue-reference: we expect one move (for SPS transparent
254	  // conversion), no copies.
255	  EXPECT_EQ(OpCounter<1>::moves(), 1U);
256	  EXPECT_EQ(OpCounter<1>::copies(), 0U);
257	
258	  // Pass-by-const-lvalue-reference: we expect one move (for SPS transparent
259	  // conversion), no copies.
260	  EXPECT_EQ(OpCounter<2>::moves(), 1U);
261	  EXPECT_EQ(OpCounter<2>::copies(), 0U);
262	
263	  // Pass-by-rvalue-reference: we expect one move (for SPS transparent
264	  // conversion), no copies.
265	  EXPECT_EQ(OpCounter<3>::moves(), 1U);
266	  EXPECT_EQ(OpCounter<3>::copies(), 0U);
267	}
